use diagram_ir::*;
use diagram_layout_geometric::{try_layout_wardley,WardleyLayoutError};
fn config()->WardleyConfig {WardleyConfig {width:900.0,height:600.0,padding:48.0,node_radius:6.0,node_label_offset:8.0,axis_font_size:12.0,label_font_size:10.0,show_grid:false,use_max_width:true,theme:WardleyTheme {annotation_stroke:"#000000".into(),annotation_text_color:"#222222".into(),annotation_fill:"#ffffff".into(),background_color:"#ffffff".into(),axis_color:"#000000".into(),axis_text_color:"#222222".into(),grid_color:"rgba(100, 100, 100, 0.2)".into(),component_fill:"#ffffff".into(),component_stroke:"#000000".into(),component_label_color:"#222222".into(),link_stroke:"#000000".into(),evolution_stroke:"#dc3545".into()}}}
fn diagram()->WardleyDiagram {WardleyDiagram{accessibility_title:None,accessibility_description:None,title:None,config:config(),stages:vec![],stage_boundaries:vec![],nodes:vec![],links:vec![],evolves:vec![],notes:vec![],annotations_box:None,annotations:vec![],forces:vec![],pipelines:vec![]}}
fn invalid(case:usize)->WardleyDiagram {let mut d=diagram();d.stages=vec!["A".into(),"B".into()];d.stage_boundaries=match case {
 0=>vec![0.5],1=>vec![0.2,0.5,1.0],2=>vec![f64::NAN,1.0],3=>vec![0.2,f64::INFINITY],4=>vec![f64::NEG_INFINITY,1.0],5=>vec![-0.1,1.0],6=>vec![0.2,1.1],7=>vec![0.8,0.2],8=>{d.stages.clear();vec![0.5]},_=>unreachable!()};d}

#[test]
fn every_bad_typed_vector_names_stage_boundaries() {
 for case in 0..9 {assert_eq!(try_layout_wardley(&invalid(case)),Err(WardleyLayoutError::StageBoundaries));eprintln!("WARDLEY-STAGE-NAMED-REFUSAL {case}");}
}
#[test]
fn all_existing_numeric_and_reference_errors_precede_stage_boundaries() {
 for (case,want) in [(0,WardleyLayoutError::Width),(1,WardleyLayoutError::Height),(2,WardleyLayoutError::Padding),(3,WardleyLayoutError::NodeRadius),(4,WardleyLayoutError::NodeLabelOffset),(5,WardleyLayoutError::AxisFontSize),(6,WardleyLayoutError::LabelFontSize),(7,WardleyLayoutError::NodeCoordinates),(8,WardleyLayoutError::EvolutionTarget),(9,WardleyLayoutError::NoteCoordinates),(10,WardleyLayoutError::AnnotationBoxCoordinates),(11,WardleyLayoutError::AnnotationCoordinates),(12,WardleyLayoutError::ForceCoordinates),(13,WardleyLayoutError::UnknownLinkEndpoint),(14,WardleyLayoutError::UnknownEvolutionComponent),(15,WardleyLayoutError::PipelineReference),(16,WardleyLayoutError::PipelineMembership),(17,WardleyLayoutError::StageBoundaries)] {
 let mut d=invalid(7);d.nodes=vec![WardleyNode{label_offset_x:None,label_offset_y:None,source_strategy:None,inertia:false,id:"P".into(),label:"P".into(),visibility:0.5,evolution:0.5,anchor:false,pipeline_parent:true},WardleyNode{label_offset_x:None,label_offset_y:None,source_strategy:None,inertia:false,id:"C".into(),label:"C".into(),visibility:0.5,evolution:0.25,anchor:false,pipeline_parent:false}];d.pipelines=vec![WardleyPipeline{parent_id:"P".into(),component_ids:vec!["C".into()]}];
 match case {0=>d.config.width=f64::NAN,1=>d.config.height=f64::NAN,2=>d.config.padding=f64::NAN,3=>d.config.node_radius=f64::NAN,4=>d.config.node_label_offset=f64::NAN,5=>d.config.axis_font_size=f64::NAN,6=>d.config.label_font_size=f64::NAN,7=>d.nodes[0].visibility=f64::NAN,8=>d.evolves.push(WardleyEvolution{component:"P".into(),target:f64::NAN}),9=>d.notes.push(WardleyNote{text:"N".into(),visibility:f64::NAN,evolution:0.5}),10=>d.annotations_box=Some((f64::NAN,0.5)),11=>d.annotations.push(WardleyAnnotation{number:1,text:"A".into(),coordinates:vec![(0.5,f64::NAN)]}),12=>d.forces.push(WardleyForce{label:"F".into(),visibility:f64::NAN,evolution:0.5,kind:WardleyForceKind::Accelerator}),13=>d.links.push(WardleyLink{dashed:false,label:None,flow:None,source:"missing".into(),target:"C".into()}),14=>d.evolves.push(WardleyEvolution{component:"missing".into(),target:0.5}),15=>d.pipelines[0].parent_id="missing".into(),16=>d.pipelines[0].component_ids.clear(),_=>{}}
 assert_eq!(try_layout_wardley(&d),Err(want),"priority{case}");eprintln!("WARDLEY-STAGE-PRIORITY {case}");
 }
}
